import re

ERROR_RE = re.compile(r'(?<![A-Za-z0-9_])ERROR(?![A-Za-z0-9_])')
KV_RE = re.compile(r'(?:service|svc|component|logger)\s*[=:]\s*"?([A-Za-z0-9_.\-/]+)"?', re.I)
BRACKET_RE = re.compile(r'\[([^\]]+)\]')
LEVELS = {"ERROR", "WARN", "WARNING", "INFO", "DEBUG", "TRACE", "FATAL", "CRITICAL"}


def _clean(tok):
    if tok is None:
        return None
    tok = tok.strip().strip('"\'')
    tok = tok.strip(" \t:;,|-")
    tok = tok.strip()
    if not tok:
        return None
    if tok.upper() in LEVELS:
        return None
    return tok


def _looks_like_timestamp(tok):
    if not tok:
        return True
    if re.match(r'^[\d:\-/.T+ ]+Z?$', tok):
        return True
    return False


def _extract_service(line, match):
    kv = KV_RE.search(line)
    if kv:
        s = _clean(kv.group(1))
        if s:
            return s

    brackets = [(m.start(), m.group(1)) for m in BRACKET_RE.finditer(line)]
    after = [b for b in brackets if b[0] >= match.end()]
    for _, raw in after:
        s = _clean(raw)
        if s and not _looks_like_timestamp(s):
            return s
    before = [b for b in brackets if b[0] < match.start()]
    for _, raw in reversed(before):
        s = _clean(raw)
        if s and not _looks_like_timestamp(s):
            return s

    tail = line[match.end():].lstrip(" \t:[]-|")
    parts = tail.split()
    if parts:
        s = _clean(parts[0])
        if s and not _looks_like_timestamp(s):
            return s
    return None


def run(task_input, tools):
    task_input = task_input if isinstance(task_input, dict) else {}
    path = None
    for key in ("path", "log_path", "file", "filename"):
        val = task_input.get(key)
        if isinstance(val, str) and val:
            path = val
            break

    result = None
    if path is not None:
        try:
            result = tools.read_log_file(path=path)
        except Exception:
            result = None
    if result is None:
        try:
            result = tools.read_log_file()
        except Exception:
            result = {}

    lines = []
    if isinstance(result, dict):
        raw = result.get("lines")
        if isinstance(raw, list):
            lines = raw

    counts = {}
    total = 0
    for line in lines:
        if not isinstance(line, str):
            continue
        m = ERROR_RE.search(line)
        if not m:
            continue
        total += 1
        service = _extract_service(line, m) or "unknown"
        counts[service] = counts.get(service, 0) + 1

    ordered = dict(sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])))
    return {"error_counts": ordered, "total": total}
